    private static void verifyStairLight(Minecraft mc){var region=new RenderRegionCache().createRegion(mc.level,SectionPos.of(STAIRS),true);var collector=new Collector();mc.getBlockRenderer().renderLiquid(STAIRS,new GuardedAccess(region,false),collector,region.getBlockState(STAIRS),Fluids.WATER.defaultFluidState());collector.finish();Integer nativeLight=null;for(int i=0;i+3<collector.points.size();i+=4){boolean top=true;for(int j=0;j<4;j++)top&=collector.points.get(i+j)[1]>(STAIRS.getY()&15)+.5;if(top){var point=collector.points.get(i);nativeLight=(int)point[3]|(int)point[4]<<16;break;}}need(nativeLight!=null,"native liquid light reference top quad");int compared=0;for(var face:data(mc,STAIRS).faces)if(face.facing()==Direction.UP.get3DDataValue()){need(face.packedLight()==nativeLight,"opaque stair fluid top light matches actual native liquid renderer");compared++;}need(compared>0,"actual fluid top light cases");System.out.println("[vandorlabs][modern] contained-fluid-light PASS opaque stair free surface equals native renderer packed light "+nativeLight);}
    private static int boundary(List<double[]> points,double x){int count=0;for(int i=0;i+3<points.size();i+=4){boolean on=true;for(int j=0;j<4;j++)on&=Math.abs(points.get(i+j)[0]-x)<.002;if(on)count++;}return count;}
    private static List<double[]> render(Minecraft mc,BlockPos pos,BlockAndTintGetter access){var collector=new Collector();mc.getBlockRenderer().renderLiquid(pos,access,collector,access.getBlockState(pos),access.getFluidState(pos));collector.finish();return collector.points;}
    private static final class Collector implements VertexConsumer {final List<double[]> points=new ArrayList<>();double[] current;void finish(){if(current!=null){points.add(current);current=null;}}@Override public VertexConsumer addVertex(float x,float y,float z){finish();current=new double[]{x,y,z,0,0};return this;}@Override public VertexConsumer setColor(int r,int g,int b,int a){return this;}@Override public VertexConsumer setUv(float u,float v){return this;}@Override public VertexConsumer setUv1(int u,int v){return this;}@Override public VertexConsumer setUv2(int u,int v){current[3]=u;current[4]=v;return this;}@Override public VertexConsumer setNormal(float x,float y,float z){return this;}}
    private record GuardedAccess(BlockAndTintGetter delegate,boolean stripData) implements BlockAndTintGetter {
        @Override public BlockState getBlockState(BlockPos pos){return delegate.getBlockState(pos);}@Override public FluidState getFluidState(BlockPos pos){return delegate.getFluidState(pos);}@Override public BlockEntity getBlockEntity(BlockPos pos){throw new IllegalStateException("Native liquid worker attempted a live block-entity read");}@Override public ModelData getModelData(BlockPos pos){return stripData?ModelData.EMPTY:delegate.getModelData(pos);}@Override public float getShade(Direction direction,boolean shade){return delegate.getShade(direction,shade);}@Override public LevelLightEngine getLightEngine(){return delegate.getLightEngine();}@Override public int getBlockTint(BlockPos pos,ColorResolver resolver){return delegate.getBlockTint(pos,resolver);}@Override public int getHeight(){return delegate.getHeight();}@Override public int getMinBuildHeight(){return delegate.getMinBuildHeight();}
    }
